P.CR = {"crTitle":"Pagbasa nga Magkauban","crCopyB":"Kopyaha ang link","crTile_d":"Manguna o apil: ang telepono sa tanan mosunod sa parehas nga kapitulo ug bersikulo","crHostB":"Ako ang manguna","crHostD":"Mosunod kanako ang telepono sa tanan sa parehas nga kapitulo, parehas nga lugar sa pag-scroll, sa bersikulo nga akong i-tap, ug hangtod asa na ang pagbasa og kusog","crJoinB":"Apil","crJoinD":"Isulod ang 6 ka karakter nga code gikan sa pangulo (o i-tap ang link nga iyang gipadala, o i-scan ang QR)","crCodePh":"6 ka karakter nga code","crJoinGo":"Apil","crNamePh":"Ang inyong ngalan (aron mahibaloan sa pangulo nga anaa na kamo)","crBadCode":"Palihug isulod ang 6 ka karakter nga code","crStarting":"Gisugdan ang Pagbasa nga Magkauban…","crJoining":"Nag-apil…","crCode":"Code","crScan":"Ipa-scan kanila ang QR gamit ang kamera sa telepono, o ipa-tap ang 📡 sa panid sa pagbasa ug isulod ang code","crShareLink":"Ipadala ang link sa pagdapit","crInviteMsg":"Gidapit ko kamo nga magbasa uban nako sa 321 Interaktibong Bibliya. I-tap ang link sa ubos aron moapil (code {0}):","crMembers":"{0} ang miapil","crNone":"Wala pay miapil — i-share ang link o QR sa tanan","crEnd":"Tapuson","crLeaveB":"Gawas","crInv":"Pagdapit","crHostBar":"Nanguna: {0}","crGuestBar":"Nagabasa uban kang {0}","crWait":"Nagkonektar…","crOff":"wala sa panid sa pagbasa","crFollow":"Balik sa pangulo","crFree":"Motan-aw ko nga mag-inusara","crFollowB":"Motan-aw ko nga mag-inusara","crFreeB":"Balik sa pangulo","crFollowOn":"Nagasunod sa pangulo","crFreeOn":"Mahimo kamong motan-aw nga dili mosunod — i-tap ang “Balik sa pangulo” aron mobalik","crJoined":"Miapil si {0}","crLeft":"Migawas si {0}","crEnded":"Gitapos sa pangulo ang Pagbasa nga Magkauban. Panalanginan unta kamo sa Ginoo!","crNoRoom":"Wala makita kini nga sesyon. Susiha ang code, o ipasugod pag-usab sa pangulo","crLostT":"Nawala ang koneksyon — mahimo kamong moapil pag-usab","crLibErr":"Wala ma-load ang bahin sa Pagbasa nga Magkauban — susiha ang network","crSent":"Napadala sa pangulo","crAway":"Anaa ang pangulo sa lain nga panid","crGuest":"Higala","crLeader":"Pangulo","crCopied":"Nakopya na ang link","crNoShare":"Dili suportado ang pag-share niini nga device","crGuestTip":"Bisan kanus-a, mahimo ninyong i-tap ang “Motan-aw ko nga mag-inusara”, ug unya i-tap ang “Balik sa pangulo” aron moadto kung asa ang pangulo. Ang inyong mga highlight ug bookmark naa ra sa inyong kaugalingong telepono.","crTip":"Kung nakaapil na ang tanan, bisan asa moadto ang pangulo — unsang kapitulo, unsang lugar sa pag-scroll, unsang bersikulo ang iyang i-tap, ug hangtod asa ang iyang pagbasa og kusog — mosunod ang telepono sa tanan, sa kaugalingong pinulongan ug gidak-on sa letra sa matag usa (bisan kon ang pangulo nagabasa sa Tradisyonal nga Intsik ug kamo sa English, makita ninyo parehas ang kapitulo ug bersikulo). Aron ipakita sa TV, gamita ang screen mirroring sa inyong telepono (AirPlay / Chromecast)."};
P.QBANK = ["Unsa ang gipakita niining tudling kanako bahin kon kinsa ang Dios?","Unsang hakog nga karaang pagkatawo sa sulod nako ang gibutyag niining tudling?","Kon tugotan nako si Jesus nga maghari niini nga butang, unsa may akong buhaton?","Unsang panig-ingnan ang gipakita kanako ni Ginoong Jesus dinhi?","Unsang lakang ang gitudlo kanako sa Balaang Espiritu nga buhaton karong adlawa pinaagi niini nga pulong?","Ngano nga napakyas ang mga tawo dinhi? Garbo ba o kahadlok ang gamut?","Giunsa ako pagtabangi niining tudling sa pagpuyo sa kinabuhi sa Wu Ji (pagkawalay-kaugalingon)?","Unsang relasyon nako ang angayang gamitan niining tudling?","Unsay kalabutan niining tudling sa linya sa Amahan Namo nga “Moabot ang imong gingharian”?","Hatagi ko og usa ka hulagway gikan sa adlaw-adlaw nga kinabuhi aron masabtan nako ang kinauyokan niining tudling."];
P.QAUD = {"seeker":["Unsay kalabutan niining tudling sa akong kinabuhi karon?","Dili pa ako Kristiyano. Unsay buot ipasabot niining mga pulonga alang kanako?","Aduna bay tinuod nga Dios? Unsa ang mga hinungdan aron motuo?","Ngano nga giingon sa Bibliya nga ang matag tawo nagkinahanglan kang Jesus?","Daghan kaayo kog pit-os. Unsang praktikal nga tabang ang gihatag sa Bibliya kanako?","Unsay buot ipasabot sa “sala” dinhi? May kalabotan ba kini kanako?","Kanunay isulti sa mga Kristiyano ang “grasya”. Unsa kini sa yanong pagkasulti?","Kon gusto pa akong makaila og dugang, asa ako magsugod?"],"teen":["Unsay kalabutan niining tudling sa akong adlaw-adlaw nga kinabuhi, sama sa eskwelahan, mga higala, ug telepono?","Kon kini nga tudling mao ang mensahe sa Dios para lang nako, unsa kaha ang isulti niini?","Tanan nagbuhat niini. Katingad-an ba kon dili ko mobuhat? Unsay giingon sa Kasulatan?","Mahimo ba ninyong ipasabot kining tudling pinaagi sa usa ka dula o salida?","Unsay makahibulong o wala kaayo mahibaloi niining tudling?","Dako kaayo ang pit-os sa eksamen. Unsang kusog ang gihatag niining tudling kanako?","Dili ko makapasaylo sa usa ka tawo. Giunsa ako pagtabangi niining tudling?","Nakita ba gyud ako sa Dios? Unsa ang naghimo kanako nga takos higugmaon?"],"kid":["Unsa ang istorya niini? Palihug sultihi ako.","Unsay gibuhat sa Dios niini nga istorya?","Gihigugma ba ako ni Ginoong Jesus? Giunsa nako pagkahibalo niini?","Kinsa ang labing maisug niini nga istorya? Ngano?","Unsaon nako pagkahimong sama sa mga tawo niini nga istorya?","Tudloi ko ug mubo nga bersikulo nga akong mahinumdoman.","Nag-away mi sa akong labing suod nga higala. Unsa kaha ang buhaton ni Ginoong Jesus?","Tudloan mo ba ako ug gamayng pag-ampo?"]};
P.AUD2 = {"elder":{"q":["Sa labing yano nga pulong, unsa man ang giingon niini nga tudling?","Unsang paglipay ang gihatag niining tudling sa mga tigulang na?","Nagkahuyang na ang akong lawas. Giunsa ako pag-atiman sa Dios?","Kanunay kong gibati nga nag-inusara. Unsay gihatag niining tudling kanako?","Giunsa nako pagpasa ang akong pagtuo sa akong mga anak ug mga apo?","Aduna pay mga butang nga dili nako maluwas. Giunsa ako pagtudloi niining tudling sa pagsalig niini sa Ginoo?","Tigulang na ako. Unsa pa may akong mabuhat alang sa Dios?","Palihug sulati ko ug mubo nga pag-ampo nga akong ihatag sa Ginoo."],"fu":["Panglawas","Kamingaw","Pamilya","Pagsalig","Paglaum","Pag-ampo"],"rw":["Nahuman na ninyo ang tibuok libro sa {nm}!","Adlaw-adlaw kamong nagpadayon hangtod dinhi. Nahinumdoman sa Dios kining pagkamatinud-anon, ug kini panig-ingnan alang kanamong mga gagmay."],"res":["Walay problema, hinay-hinay lang ta. Kon basahon pag-usab, mas klaro ang kahulogan.","Maayo kaayo! Daghan kamo og nahinumdoman niini nga kapitulo.","Maayo kaayo! Buhi ang pulong sa Dios sa inyong kasingkasing."]},"single_parent":{"q":["Ako ra ang nagdala sa gibug-aton sa pamilya. Unsang paglipay ang gihatag niining tudling kanako?","Gikapoy na kaayo ako ug gibati nako nga wala ako makatuman sa akong katungdanan sa akong mga anak. Giunsa ako pagtan-aw sa Dios?","Giunsa pag-atiman sa Dios ang mga ilo ug mga balo, ug unsay buot ipasabot niini alang kanako?","Bug-at kaayo ang kakulangon sa kwarta. Unsay gihatag niining tudling kanako?","Mosukli ang akong anak ug kusog kaayo ang iyang mga gibati. Unsay angay nakong buhaton?","Wala ko mahibalo kon unsaon pagsulti sa akong anak nga wala namo kauban ang iyang amahan (o inahan).","Gibati nako nga nag-inusara kaayo ako. Giunsa nako paghangyo og tabang sa iglesya o sa akong mga igsoon sa pagtuo?","Palihug sulati ko ug mubo nga pag-ampo nga mahimo nakong ampoon sulod sa lima ka minuto."],"fu":["Kakapoy","Mga anak","Kwarta","Paghangyo og tabang","Paglaum","Pag-ampo"],"rw":["Nahuman na ninyo ang tibuok libro sa {nm}!","Dili sayon ang padayon nga pagbasa sa Bibliya samtang nag-inusara ninyong gidala ang pamilya. Gitan-aw sa Dios ang matag lakang ninyo, ug kauban ninyo siya."],"res":["Walay problema, daghan na kaayo kamog paningkamot. Basaha pag-usab kon aduna kamoy panahon.","Maayo kaayo! Bisan sa busy kaayo, daghan kamog nahinumdoman.","Maayo kaayo! Gisuportahan kamo sa pulong sa Dios."]},"single":{"q":["Isip usa ka walay kapikas, unsay giingon niining tudling kanako?","Gibati nako ang kamingaw. Unsay gihatag niining tudling kanako?","Kinsa ako diha kang Kristo, ug unsa ang bili nako?","Giunsa nako pagsalig sa Dios samtang naghulat ako?","Unsang kaalam ang gihatag sa Bibliya bahin sa mga relasyon?","Giunsa paggamit alang sa Dios ang panahon ug kusog sa usa ka walay kapikas?","Giunsa nako pagbuhat og maayong relasyon sa iglesya ug sa mga higala?","Palihug sulati ko ug mubo nga pag-ampo alang sa usa ka walay kapikas."],"fu":["Kamingaw","Pagkatawo","Paghulat","Mga relasyon","Katuyoan sa kinabuhi","Pag-ampo"],"rw":["Nahuman na ninyo ang tibuok libro sa {nm}!","Nagpadayon kamo bisan nag-inusara, ug sa atubangan sa Dios hingpit ug mahal ang inyong mga adlaw."],"res":["Walay problema, hinay-hinay lang ta. Kon basahon pag-usab, mas klaro ang kahulogan.","Maayo kaayo! Nasabtan ninyo ang kinauyokan niini nga kapitulo.","Maayo kaayo! Maningkamot kamo, ug nagapamaklad ang pulong sa Dios diha kaninyo."]},"parent":{"q":["Isip ginikanan, unsay gipahinumdom kanako niining tudling?","Dili maminaw ang akong anak ug kusog kaayo ang iyang mga gibati. Unsaon nako pagtubag?","Giunsa nako pagbalanse ang disiplina ug grasya?","Giunsa nako pagpakigsulti og maayo sa tin-edyer nga anak?","Kanunay ko nga masuko sa akong anak ug human niana makonsensya ko. Unsa na may akong buhaton?","Giunsa nako pagdala sa akong anak aron makaila siya sa Dios, ug dili lang magsimba?","Dili mi magkauyon sa akong kapikas sa pagpadako sa anak. Unsay giingon niining tudling?","Palihug sulati ko ug mubo nga pag-ampo sa panalangin alang sa akong anak."],"fu":["Pag-estorya","Disiplina","Konsensya","Kapikas","Pagtuo","Pag-ampo"],"rw":["Nahuman na ninyo ang tibuok libro sa {nm}!","Ang adlaw-adlaw nga pagbasa sa Kasulatan taliwala sa kabusyhan sa pagpadako og anak mao ang labing maayong panig-ingnan nga mahatag ninyo kanila."],"res":["Walay problema, hinay-hinay lang ta. Basaha pag-usab kon aduna kamoy higayon.","Maayo kaayo! Nasabtan ninyo ang kinauyokan niini nga kapitulo.","Maayo kaayo! Nagapamaklad ang pulong sa Dios sa inyong panimalay."]},"couple":{"q":["Isip magtiayon, unsay giingon niining tudling kanamo?","Human sa matag away, mohugno ang among relasyon. Giunsa nga ang usa kanamo makahimo sa unang lakang sa pagpasig-uli?","Giunsa nako pagsulti ang sulod sa akong kasingkasing aron madungog kini sa akong kapikas?","Gipasakitan ako sa akong kapikas. Kinahanglan ba gyud nakong mopasaylo?","Dili mi magkauyon bahin sa kwarta ug mga buluhaton sa balay. Unsay among buhaton?","Giunsa namo pag-ampo nga magkauban ug pagpaduol sa Dios nga magtingub?","Gilayo mi sa usag usa sa kabusyhan sa kinabuhi. Giunsa namo pagpaduol pag-usab?","Palihug sulati kami ug mubo nga pag-ampo sa panalangin alang sa among kaminyoon."],"fu":["Pag-estorya","Pagpasaylo","Pagkaduol","Usa ka kasingkasing","Pagbasa nga magkauban","Pag-ampo"],"rw":["Nahuman na ninyo nga magkauban ang tibuok libro sa {nm}!","Ang magtiayon nga magkauban nga moduol sa pulong sa Dios nagbarug sa lig-on nga patukoranan."],"res":["Walay problema, hinay-hinay lang ta. Basaha pag-usab nga magkauban sa usa ka gabii.","Maayo kaayo! Nasabtan ninyong duha ang kinauyokan niini nga kapitulo.","Maayo kaayo! Nagapamaklad ang pulong sa Dios sa inyong kaminyoon."]},"pastor":{"q":["Sa pagseserbisyo, unsay giingon niining tudling kanako?","Palihug tabangi ko sa pagpangita og balangkas sa mensahe ug sugod-punto alang niining tudling.","Gikapoy na kaayo ako ug hapit na akong maluya sa tanan. Unsang paglipay ang gihatag niining tudling kanako?","Giunsa nako pag-atubang sa pagsaway ug dili pagsinabtanay sulod sa iglesya?","Unsay giingon niining tudling bahin sa pagpangulo sa grupo nga usa ang kasingkasing?","Giunsa nako pagbantay sa akong personal nga relasyon sa Dios taliwala sa busy nga pag-alagad?","Giunsa nako pagpastor sa mga huyang, nasamdan, ug mga mibiya sa iglesya?","Palihug sulati ko ug mubo nga pag-ampo sa pagpataliwala alang sa iglesya ug sa akong mga kauban sa pag-alagad."],"fu":["Mensahe","Pagpastor","Grupo","Pahulay","Gubat sa espiritu","Pagpataliwala"],"rw":["Nahuman na ninyo ang tibuok libro sa {nm}!","Ang pagpabilin nga duol sa pulong sa Dios taliwala sa busy nga pag-alagad mao ang labing lawom nga gamut sa pagpastor."],"res":["Walay problema, hinay-hinay lang ta. Basaha pag-usab kon aduna kamoy higayon.","Maayo kaayo! Nasabtan ninyo ang kinauyokan niini nga kapitulo.","Maayo kaayo! Ang pulong sa Dios nagpakaon una sa magbalantay, unya mosangpot sa panon."]}};
