P.Q20 = {"adult":["Ang utang sa balay ug ang matrikula sa mga bata nagpapas-an kanako. Unsang paglaum ang gihatag niining tudling?","Nagtrabaho ko og maayo, apan kanunay gihapon kong mobati og kawalay-sulod. Ngano man?","Pipila na ka adlaw nga wala kami nag-estoryahanay sa akong kapikas. Unsa ang unang ipabuhat kanako niining tudlinga?","Dili nako mapasaylo ang tawo nga nakasakit kanako. Giunsa ako pagtabang ni Jesus nga buhian kini nga kasakit?","Dili ko sigurado kung naa ba ang Dios. Unsa ang mga hinungdan aron motuo?","Ngano nga ang mga maayong tawo nag-antos man? Asa man ang Dios?","Daghang tuig na kong nagtuo, apan ang pag-ampo murag nakigsulti lang ko sa akong kaugalingon. Unsay angay nakong buhaton?","Ngano nga kinahanglang mamatay si Jesus diha sa krus? Unsa may kalabotan niini kanako?","Adunay mga sayop nga akong nahimo kaniadto. Dawaton ba gihapon ako sa Dios?","Ang akong anak gahi og ulo ug mapahitas-on. Giunsa nako pagpaambit niining tudlinga aron makauban ko niya?","Kung mawad-an og trabaho o malumsan ang negosyo, giunsa sa mga nagsalig kang Jesus ang pagpadayon?","Tigulang ug masakiton na ang akong mga ginikanan ug gikapoy na kaayo ako. Giunsa ako paglipay niining tudlinga?","Kanunay kong nabalaka ug dili makatulog. Unsa ang kalinaw nga gisulti ni Jesus?","Giunsa nako pagpaambit kang Jesus sa mga paryente o ka-trabaho nga wala motuo, nga dili sila masuko o mailad?","Gusto kong mosunod kang Jesus, apan nahadlok kog tamay-tamayon o supakon sa akong pamilya. Unsay buhaton nako?","Unsa ang kalahian sa pagsalig kang Jesus sa pagsimba sa ubang mga dios o sa pagkahimong maayong tawo lang?","Giunsa sa usa ka tawo pagsugod sa pagkaila kang Jesus? Unsang gamay nga lakang ang mahimo nako karong adlawa?","Dali kong masuko ug dili makabungkag sa daotang batasan. Mabag-o ba gayod ni Jesus ang usa ka tawo?","Nahadlok ko sa kamatayon. Unsa ang buot ipasabot ni Jesus sa kinabuhing dayon?","Kung gusto nakong ihatag ang akong kinabuhi kang Jesus karong adlawa, giunsa nako pag-ampo?"],"teen":["Giunsa pagkonektar niining tudlinga sa akong kinabuhi sa eskwelahan?","Bug-at kaayo ang pit-os sa eksamen. Hinungdanon ba gihapon ako kung ubos ang akong grado?","Ang tanan aduna nay grupo ug mibati kog gisalikway. Giunsa ako pagtan-aw ni Jesus?","Gibiaybiay ko o gibudhian sa usa ka higala ug nasuko ko. Unsay buhaton ni Jesus?","Mibati kog dili ko gwapo o maayo igo. Gihigugma ba gayod ako sa Dios?","Kanunay nag-away ang akong ginikanan o sobra silang mokontrol ug nasuko na ko. Unsay giingon sa Bibliya?","Giingon sa akong mga higala nga pamahiin ang Kristiyanismo ug ang siyensya ang husto. Unsaon nako pagtubag?","Naay akong gusto — ok ba ang pag-date? Unsang kaalam ang gihatag sa Bibliya?","Dili nako mapugngan ang pag-scroll o pagdula og games. Unsay mahimo nako?","Ngano pa man motuo kang Jesus? Unsa kaha kung dili ko motuo?","Tinuod bang tawo si Jesus? Unsay mga ebidensya?","Adunay sayop nga akong nahimo ug nahadlok kong isulti kini sa bisan kinsa. Pasayloon ba ako sa Dios?","Kanunay kong kabalaka ug masulob-on. Mahimo ba kong dad-on ni Jesus?","Ang tanan nag-ingon nga “pagkaikaw ra gyud” — mawad-an ba kog kagawasan kung mosunod kang Jesus?","Kung gihigugma ako sa Dios, ngano nga gitugotan Niya nga mahitabo kanako ang mga makasubo nga butang?","Gusto kog tinuod nga mga higala. Giunsa ako pagtudlo ni Jesus nga mahimong higala?","Kung gusto kong mosunod kang Jesus, unsa ang unang buhaton? Kinahanglan ba kong hingpit?","Molihok ba gyud ang pag-ampo? Mahimo ba kong makigsulti sa Dios sa akong kaugalingong pulong?","Wala ko mahibalo kung unsay tun-an o buhaton sa umaabot. Giunsa nako pagsagubang sa kaugmaon?","Giunsa nako pagpasabot sa akong mga higala, sa akong kaugalingong pulong, kung kinsa si Jesus?"],"kid":["Unsa ang istorya niini? Palihug sultihi ko.","Kinsa si Jesus? Asa Siya nagpuyo?","Gihigugma ba gyud ako ni Jesus? Unsaon nako pagkahibalo?","Asa ang Dios? Dili nako Siya makita — unsaon Niya pagpamati kanako?","Adunay sayop akong nahimo ug nasuko sila Mama ug Papa. Nasuko ba pud si Jesus kanako?","Nag-away mi sa akong labing suod nga higala. Unsay buhaton ni Jesus?","Nahadlok ko sa kangitngit ug sa daotang damgo. Mapanalipdan ba ko ni Jesus?","Lisod kaayo ang homework ug ayaw na kog eskwela. Matabangan ba ko ni Jesus?","Ngano nga namatay si Jesus diha sa krus?","Ngano nga nabuhi pag-usab si Jesus human siya mamatay?","Nagsakit ang akong lola (o ang akong iro). Pagawasion ba siya ni Jesus?","Unsa ang langit?","Naay tawo sa eskwelahan nga dautan kanako. Unsay mahimo nako? Unsay giingon ni Jesus?","Tudloan ba ninyo ako unsaon pag-ampo? Unsay akong isulti?","Kinsay naghimo sa Dios?","Mahimo ba kong labing suod nga higala ni Jesus? Unsaon?","Giunsa nako pagkat-on nga malipayong mopaambit sa ubang mga bata?","Unsa ang “sala”? Naa ba pud koy sala?","Tudloi ko og usa ka mubo nga bersikulo nga akong mahinumdoman.","Gusto kong mopuyo si Jesus sa akong kasingkasing. Unsay akong isulti?"],"seeker":["Wala pa gayod ko makabasa sa Bibliya. Giunsa pagkonektar niining tudlinga sa akong kinabuhi karon?","Naa ba gyud ang Dios? Unsa ang mga hinungdan aron motuo?","Ngano nga daghan kaayong pag-antos sa kalibotan? Ngano nga wala kini pugngi sa Dios?","Dili ba mga tawo ang nagsulat sa Bibliya? Ngano nga mahimo ko kining pagasalihan?","Nabuhi ba gyud si Jesus? Unsay nakapahinungdan Kaniya?","Sa akong hunahuna maayo kong tawo. Ngano nga kinahanglan ko pa gihapon si Jesus?","Dili ba tanang relihiyon nagtudlo lang sa pagbuhat og maayo? Unsay lahi sa Kristiyanismo?","Daghan kog pit-os ug mibati kog kawalay-sulod. Unsang praktikal nga tabang ang mahatag sa Bibliya?","Adunay mga makalilisang nga butang nga akong nahimo. Dawaton ba ang usa ka tawo sama nako sa Dios?","Ang akong pamilya nagsimba sa mga katigulangan (o nagsunod sa lain nga pagtuo). Ang pagsalig kang Jesus ba maoy pagwalay-respeto o hinungdan nga isalikway ko?","Nagkasumpaki ba ang siyensya ug pagtuo?","Nadungog nako nga ang pagsunod kang Jesus nagpasabot sa pagbiya sa daghang kalipay. Tinuod ba kini?","Ngano nga kinahanglang mamatay si Jesus? Unsa may kalabotan sa Iyang kamatayon kanako?","Tinuod ba ang pagkabanhaw? Unsa ang basihan niini?","Nakakita kog mga mapakaaron-ingnon sa simbahan ug nagduha-duha ko tungod niana. Unsaon nako pagtan-aw niini?","Unsa ang buot ipasabot sa “pagtuo kang Jesus”? Kinahanglan ko bang masabtan ang tanan o ayuhon una ang akong kinabuhi?","Maayo man ang akong kahimtang bisag walay pagtuo. Unsa ang akong makuha kung motuo ako kang Jesus?","Gusto kong makaila kang Jesus sa akong kaugalingon. Giunsa nako pagsugod sa pagbasa sa Bibliya?","Kung mosalig ko kang Jesus, unsa ang unang lakang? Unsaon nako pag-ampo?","Daghan pa kog pangutana. Mahimo ba kong mangutana samtang naglakaw ug hinay-hinay nga magdesisyon?"],"elder":["Tigulang na ko ug kanunay nagsakit. Giunsa ako paglipay niining tudlinga?","Busy ang akong mga anak (o nagtrabaho sila sa gawas sa nasud) ug mibati kog nag-inusara. Giunsa ako pagkauban ni Jesus?","Nahadlok ko sa kamatayon ug kung asa ko moadto. Unsay giingon ni Jesus?","Namatay na ang akong kapikas ug mibati ang akong kasingkasing nga walay sulod. Unsang paglipay ang gihatag sa Bibliya?","Sa tibuok kong kinabuhi nagsimba ko sa mga imahen ug nag-ampo sa mga kalag sa katigulangan. Ulahi na ba kaayo nga mosalig kang Jesus karon?","Ang akong mga anak ug apo wala motuo. Unsay mahimo nako alang kanila?","Adunay mga butang nga akong nahimo sa akong pagkabatan-on nga akong gikahinulsulan. Pasayloon ba ko sa Dios?","Huyang na ang akong mga mata ug dili na ko kabasa og maayo. Giunsa nako pagpaminaw sa Bibliya ug pag-ampo?","Niining panuigona, unsa ang kahulogan sa kinabuhi? Unsa pa ang gusto sa Dios kanako?","Kanunay kong dili makatulog ug nagadagan ang hunahuna. Mahatagan ba ko ni Jesus og kalinaw?","Dili maayo ang pagtagad sa akong mga anak o gubot ang pamilya. Giunsa nako pagbiya sa kasuko?","Nahadlok ko nga mahimong palas-anon sa akong mga anak. Giunsa kini pagtan-aw niining tudlinga?","Si Jesus miingon nga ang mga nagsalig Kaniya may kinabuhing dayon. Unsa ang gipasabot niini?","Ang akong kahimtang sa lawas wala motugot nga makasimba ko sa simbahan. Giunsa nako pagsimba sa balay?","Magsumpaki ba ang pagtahod sa mga katigulangan ug ang pagsunod kang Jesus? Giunsa nako pagtahod sa akong namatay nga mga ginikanan?","Giunsa nako pagpaambit sa pagkamaayo ni Jesus sa mga karaang higala ug silingan?","Human ko mosalig kang Jesus, giunsa pagpuyo ang ordinaryong mga adlaw?","Gusto kong magpabawtismo. Unsay angay kong andamon?","Sa katapusan sa kinabuhi, giunsa ako pagkauban ni Jesus? Unsay mahimo sa akong pamilya?","Tudloi ko og usa ka sayon nga sentensya nga magamit nako sa pag-ampo kang Jesus matag adlaw."],"single_parent":["Ako ang nanay ug tatay ug gikapoy na kaayo ko. Giunsa ako pagtabang ni Jesus?","Kanunay kong mibati nga nakapahigawad ko sa akong anak. Giunsa ako paglipay niining tudlinga?","Gipit ang kwarta ug wala ko mahibalo kung unsaon pagtapos sa bulan. Unsang paglaum ang gihatag sa Bibliya?","Lawom ang pagkasakit nako sa akong gibulagan ug dili nako siya mapasaylo. Giunsa nako pagpagawas niini?","Mangutana ang akong anak, “Asa na si Papa (o Mama)?” Unsaon nako pagtubag?","Mapungot o mapahitas-on ang akong anak. Giunsa nako paggamit sa Kasulatan aron makauban ko niya?","Kanunay kong mibati nga gitamay o gilabelan ko. Giunsa ako pagtan-aw sa Dios?","Nagsakit ang akong anak sa tungatunga sa gabii ug nag-inusara ko ug nalisang. Makatabang ba ang pag-ampo?","Nag-inusara ko ug walay kahibalag nga makigsulti. Giunsa ako pagkauban ni Jesus?","Aduna pa bay higayon sa gugma o pag-minyo pag-usab? Unsang kaalam ang gihatag sa Bibliya?","Nasuko ko sa Dios — ngano nga nabungkag ang akong pamilya?","Sa tanan nga kabusyhan, giunsa nako pagtabang sa akong anak nga makaila kang Jesus?","Giunsa nako pagtudlo sa akong anak sa pag-ampo ug pagbasa sa Bibliya nga dili siya pugson?","Gipit ako sa trabaho ug pag-atiman sa bata. Giunsa nako pagpugong sa pagkasad-an nga mopaubos kanako?","Gibulag ko (o napawalay-bisa ang akong kaminyoon). Dawaton ba ko gihapon sa Dios? Angay ba ko nga mosalig kang Jesus?","Gusto kong magsugod pag-usab. Unsang bag-ong sinugdan ang mahatag ni Jesus kanako?","Kang kinsa ako makaduol alang sa tabang? Giunsa ako pagsuportahan sa usa ka simbahan o komunidad sa pagtuo?","Nahadlok ko nga masubli sa akong anak ang akong mga sayop. Giunsa nako paghatag kaniya og seguridad?","Karong adlawa gikinahanglan nako ang usa lang ka sentensya aron malahutay ko. Palihug hatagi ko og paglaum.","Gusto kong itugyan kang Jesus kining among panimalay. Unsaon nako pag-ampo?"],"single":["Ang pagkasolo usahay maghimo kanakog nag-inusara. Giunsa sa Dios pagtan-aw ang akong kamingaw?","Gipugos ko sa akong pamilya nga magminyo ug mibati kog pit-os. Giunsa nako pagsagubang niini?","Gusto kong magminyo apan wala pa nako makaplagi ang husto nga tawo. Nag-andam ba ang Dios og usa para nako?","Nasakitan ko sa gugma ug dili na ko makasalig pag-usab. Giunsa nako pag-ayo?","Mahimo ba kong makig-date sa lahi nga pagtuo? Unsay giingon sa Bibliya?","Sobra kong naghunahuna sa giingon sa uban ug mibati nga kapakyasan ang pagkasolo. Tinuod ba kini?","Gikuha sa trabaho ang akong tibuok oras ug wala nakoy kaugalingong kinabuhi. Unsa ang kahulogan sa kinabuhi?","Maayo ra ko nga nag-inusara — ngano nga kinahanglan ko pa ang Dios?","Giunsa nako pagkahibalo kung ang usa ka tawo husto para nako? Unsang kaalam ang anaa?","Nakigbisog ko sa tinguha o sa mga butang online. Matabangan ba ko ni Jesus?","Nahadlok ko nga tumigulang nga nag-inusara. Unsang seguridad ang gihatag sa Bibliya?","Ang tanan nakong higala minyo na ug aduna nay anak. Giunsa nako paglikay sa kasina ug pagtandi?","Unsay gusto sa Dios nga buhaton nako niining panahon sa pagkasolo?","Nahigawad ko sa gugma ug sa Dios. Mahimo ba kong mahinuklugon uban Kaniya?","Dili pa ko Kristiyano. Ok ra ba nga ako, nga solo, mosulay sa pagkaila kang Jesus?","Gusto kong mosunod kang Jesus apan nabalaka ko nga mausab kaayo ang akong kinabuhi. Unsay akong mawala?","Giunsa nako pagpangita og tinuod nga mga higala ug pagbuhat og lingin nga mosuporta kanako?","Mabalaka ko nga walay moabaga kanako. Unsa ang gugma ni Jesus?","Dili ko motuo nga ang gugma mahimong walay kondisyon. Unsay buhaton nako niini?","Kung gusto nakong ihatag ang akong kinabuhi kang Jesus, giunsa nako pagsugod?"],"parent":["Dili gusto sa akong anak ang pagtuon ug sa tibuok adlaw naa siya sa telepono. Nabalaka ko — unsay buhaton nako?","Mosupak ang akong anak ug masuko ko. Giunsa ako pagtabang niining tudlinga?","Dili magkauyon mi sa akong kapikas bahin sa pag-atiman sa bata ug mag-away mi. Unsay angay namong buhaton?","Giunsa nako pagpakigsulti sa akong anak bahin kang Jesus nga dili mamati nga nagsermon?","Mangutana ang akong anak, “Asa ang Dios?” ug “Ngano nga namatay ang mga tawo?” Unsaon nako pagtubag?","Kanunay kong makasinggit sa akong anak ug magmahay ko. Pasayloon ba ko sa Dios?","Nahadlok ko nga mabiaybiay ang akong anak o makauban sa daotang mga higala. Giunsa nako pag-ampo alang kaniya?","Ubos ang grado sa akong anak. Giunsa nako paglikay sa pagtandi ug pagdugang pit-os?","Lisod ang paghiusa sa trabaho ug pamilya ug nahadlok kong makalimtan ang pagdako sa akong anak. Unsay mahimo nako?","Masakiton ang akong anak o aduna siyay espesyal nga panginahanglan ug gibasol nako ang akong kaugalingon. Giunsa kini pagtan-aw sa Dios?","Dili makigsulti kanako ang akong tin-edyer. Giunsa nako pagduol pag-usab?","Dili nako masulbad bisan ang akong kaugalingon. Giunsa nako pagkahimong ehemplo?","Naay wala motuo sa among balay. Giunsa nako pagpuyo sa akong pagtuo sa balay?","Giunsa nako pagbag-o sa pag-ampo ug pagbasa sa Bibliya uban sa akong anak ngadto sa malipayong batasan sa pamilya?","Mibiya ang akong anak sa pagtuo o mibiya sa simbahan. Unsay mahimo nako?","Mangutana ang akong anak, “Mama/Papa, nagtuo ka kang Jesus — kinahanglan ba ko pud?” Unsaon nako pagtubag?","Giunsa nako pagtudlo sa akong anak sa pagsagubang sa kapakyasan ug kasagmuyo?","Gusto nako ang labing maayong kinabuhi alang sa akong anak. Unsay giingon sa Bibliya nga labing hinungdanon?","Nipis ang akong pagtuo. Giunsa nako pagdala sa akong anak sa pagkaila kang Jesus?","Alang sa tibuok kinabuhi sa akong anak, giunsa nako pag-ampo alang kaniya karong adlawa?"],"couple":["Wala mi nag-estoryahanay human sa among away. Kinsa ang angay nga mag-una sa pagsulti? Unsay giingon niining tudlinga?","Mas lisod na ang pagdawat sa mga kakulangan sa akong kapikas. Unsay buhaton nako?","Kanunay mi mag-away tungod sa kwarta. Unsang kaalam ang gihatag sa Bibliya sa magtiayon?","Naipit ko tali sa akong kapikas ug sa akong mga ugangan. Unsay angay nakong buhaton?","Wala motuo kang Jesus ang akong kapikas. Giunsa nako paghigugma kaniya nga dili siya pugson?","Dugay na mi nga wala makigsulti og tinuod. Giunsa namo pagkonektar pag-usab?","Gisakit nila ko. Makapasaylo ba gyud ko kanila?","Gikapoy mi pareho sa pag-atiman sa mga bata. Giunsa namo paglikay nga mag-agaw mi sa kasuko?","Mibati kog mas daghan akong gihatag ug nasuko ko. Giunsa ako pagtudlo ni Jesus?","Lahi kaayo ang among kinaiya. Giunsa namo pagpuno sa usag usa imbes nga magkapoy?","Wala mi sanay mag-ampo nga magkauban. Giunsa namo pagsugod?","Dili mi magkasabot bahin sa among kaugmaon (paglihok, trabaho). Giunsa namo pagkahiusa sa kasingkasing?","Nabugnaw na ang among gugma. Giunsa namo pagpasiga niini pag-usab?","Nahadlok ko nga dili mi molahutay. Unsang paglaum ang gihatag sa Bibliya alang sa kaminyoon?","Ang “pagpasakop” ba nagpasabot nga kinahanglan ko lang mosunod sa akong kapikas?","Naubos ang akong kapikas sa trabaho, telepono o games. Giunsa nako pagpahayag sa akong gibati?","Gusto mi og panimalay nga naa si Jesus sa tunga. Unsa ang unang lakang?","Mabag-o ba gayod ni Jesus ang among kaminyoon?","Usa lang sa amoa ang nagtuo kang Jesus. Giunsa namo pagtahod sa usag usa?","Unsa ang usa ka gamay nga pag-ampo nga mahimo namong ipag-ampo nga magkauban karong gabii?"],"pastor":["Giunsa nako paghimo og tin-aw nga balangkas gikan niining tudlinga alang sa pagwali sa Dominggo?","Gikapoy na kaayo ko. Giunsa nako pag-alagad nga dili masunog?","Magkalahi og hunahuna ang akong mga kauban sa pag-alagad. Giunsa nako paggamit sa Kasulatan aron madala kami ngadto sa panaghiusa?","Naay mga miyembro nga mibiya o dili motubo ang gidaghanon. Giunsa nako paglikay sa kabalaka ug pagtandi?","Giunsa nako pag-atiman sa higala nga wala pa motuo apan nagsugod na sa pag-adto sa simbahan?","Giunsa nako pagpaambit sa Maayong Balita nga tin-aw ug malumo sa usa ka tawo nga wala motuo?","Giunsa nako pagtubag sa usa ka mangita nga lig-on ang mga pagsupak (Katoliko, Iglesia ni Cristo, tradisyonal nga pagtuo, ateyista)?","Giunsa nako pag-andam sa pagdapit sa pagsunod kang Kristo nga dili mopugos sa mga tawo?","Uga ang akong kaugalingong espirituwal nga kinabuhi. Giunsa nako pagpangita pag-usab og kusog?","Giunsa nako pagtubag sa panagbangi o pagsaway sa simbahan?","Giunsa nako pagtudlo sa mga bag-ong magtutuo gikan sa unang pagtuo hangtod sa pagtubo?","Giunsa nako pagpalambo sa mga kauban sa pag-alagad ug sa mga umaabot nga lider?","Giunsa nako pagbalanse sa pamilya ug pag-alagad nga dili tamayon ang akong pamilya?","Giunsa nako pag-ampo alang sa usa ka tawo nga naghingalo ug paglipay sa iyang pamilya?","Naay gusto nga magpabawtismo. Giunsa nako pag-andam sa klase ug sa iyang pagpamatuod?","Giingon nga lawom kaayo o nipis kaayo ang akong mga wali. Giunsa nako pagpangita sa balanse?","Giunsa nako pagpangulo sa gamay nga grupo sa pagtuon sa Bibliya nga mahimong salihan sa mga wala motuo?","Giunsa nako pagtubag sa lisod nga mga pangutana sama sa “Ngano nga ang mga maayong tawo nag-antos?”","Sa busy nga pag-alagad, giunsa nako pagbutang gihapon sa “kinabuhi una, mga relasyon sunod, pag-alagad katapusan”?","Hatagi ko og mubo nga pagtapos nga magamit nako karong adlawa sa pagpangulo sa mga miyembro sa pag-ampo."]};
P.Q20SK = {"buddhism":["Nag-awit ko og mga mantra ug dili ko mokaon og karne. Kinahanglan ko bang biyaan kini aron mosunod kang Jesus?","Giingon sa Budismo nga ang pag-antos naggikan sa pagkamapanghawid. Unsaon sa Bibliya pagtan-aw ang pag-antos sa tawo?","Gitudlo sa Budismo ang karma. Unsa ang kalahian sa “grasya” sa Bibliya sa hinungdan ug sangputanan?","Unsa ang kalahian sa reinkarnasyon sa tudlo sa Bibliya nga “usa ka kinabuhi, dayon paghukom”?","Gitudlo sa Budismo ang pagkaparehas ug kalooy. Nagtudlo ba pud si Jesus sa paghigugma sa uban?","Nagsimba ko sa Buddha alang sa kalinaw sa hunahuna. Unsa ang kalahian sa kalinaw nga gihatag ni Jesus?","Mga magtutudlo ba ang Buddha ug si Jesus? Ngano nga gitawag ni Jesus ang Iyang kaugalingon nga Manluluwas?","Gihisgotan sa Budismo ang “pagpagawas.” Giunsa sa Bibliya pagtudlo ang pagpagawas sa kabalaka ug kasuko?","Nagpraktis na kog meditasyon. Unsa ang kalahian sa Kristiyanong pag-ampo sa pagpamalandong?","Gihatagan og gibug-aton sa Budismo ang kaugalingong paningkamot. Ngano nga giingon sa Bibliya nga maluwas kita pinaagi sa grasya ug dili sa mga buhat?","Giingon sa Bibliya nga ang Dios mao ang Maglalalang. Unsa ang kalahian niini sa “kawalay-sulod” ug “nagsalig nga pagkaugmad”?","Budista ang tanan sa akong pamilya. Makasakit ba kanila ang pagsunod kang Jesus? Giunsa nako pagpakigsulti kanila?","Kung mamatay ang usa ka minahal, naghimo mi og pagbalhin sa merito. Giunsa sa mga Kristiyano pagtan-aw ang mga namatay ug ang paghandum?","Daghan kog nahimong maayong buhat. Ngano nga giingon sa Bibliya nga kinahanglan kong maluwas?","Giingon sa Budismo nga ang tanan adunay Buddha-nature. Giunsa sa Bibliya pagtan-aw ang kinaiya sa tawo ug sala?","Ngano nga ang kamatayon ni Jesus makapasaylo sa akong mga sala? Unsa may kalabotan niini sa karma?","Ang “nirvana” ba parehas sa “kinabuhing dayon” ug “langit” sa Bibliya?","Mahimo ba nga ang usa ka Budista mosunod kang Jesus sa samang higayon? Ngano nga gihatagan og gibug-aton sa Bibliya ang usa ka tinuod nga Dios?","Gusto kong makaila kang Jesus. Unsang libro o tudling ang unang basahon nako?","Kung andam akong sulayan ang pag-ampo kang Jesus, unsa ang akong masulti isip unang sentensya?"],"folk":["Ang akong pamilya nagsimba sa mga dios ug mga katigulangan. Kung mosunod ko kang Jesus, dili na ba nako kana mahimo? Ngano?","Nagsimba ko sa mga dios alang sa kalinaw ug panalipod. Mahatagan ba ko ni Jesus niana?","Gitudlo sa Bibliya ang pagtahod sa mga ginikanan. Ang pagsunod ba kang Jesus maghimo kanakog dili matinahuron?","Sa Undas atong gisaulog ang mga katigulangan. Giunsa sa usa ka Kristiyano paghandum ug pagpakita og pagtahod kanila?","Daghan ang mga dios sa among altar. Hain ang tinuod?","Pagtagna, anting-anting, pagbag-o sa swerte — unsay giingon sa Bibliya?","Tukma ba ang feng shui ug ang pagtagna sa templo? Giunsa sa mga nagsunod kang Jesus pagsagubang sa wala mahibaloi?","Nalugi ang akong negosyo ug miingon ang usa ka higala nga mag-ampo ko sa dios sa kayamanan. Giunsa ako pagtabang ni Jesus?","Naay masakiton sa among balay ug giingon sa mga tawo nga mohimo og ritwal sa kalag o moadto sa albularyo. Unsay angay nakong buhaton?","Nahadlok kong makasuko sa mga dios ug silotan. Unsa ang mahitabo niining kahadlokan kung mosunod ko kang Jesus?","Gisupak sa akong mga ginikanan ang akong pag-adto sa simbahan. Giunsa nako pagpakigsulti kanila nga dili sila masakitan?","Unsay giingon sa Bibliya bahin sa pag-ampo sa mga santos, sa mga imahen, ug sa mga anito? Tinuod ba sila?","Ngano nga usa lang ang tinuod nga Dios? Bakak ba ang tanang ubang mga dios?","Maayo ba ang kahimtang sa akong namatay nga mga paryente sa sunod nga kalibotan? Unsay mahimo nako alang kanila?","Nagsimba na ko sa daghang mga templo ug simbahan. Isalikway ba ko sa Dios?","Naay pagsimba sa among kasal ug lamay. Giunsa nako pagsalmot nga dili mailad kung mosunod ko kang Jesus?","Naa mi mga imahen ug anting-anting sa balay. Unsay buhaton nako niini human ko motuo?","Mapanalipdan ba ko ni Jesus? Unsa ang kalahian niini sa panalipod sa mga dios?","Gusto kong makaila kang Jesus. Moadto ba ko una sa simbahan, o mobasa una sa Bibliya nga ako ra?","Gusto kong mag-ampo kang Jesus. Kinahanglan ba nako ang insenso, kandila o halad? Giunsa nako pag-ampo?"],"yiguandao":["Vegetarian ko ug gihatagan nako og bili ang pagpalambo sa kaugalingon ug maayong buhat. Kinahanglan ba nakong usbon kini aron mosunod kang Jesus?","Giingon sa Yiguandao nga “ang lima ka relihiyon usa ra ang gigikanan.” Ngano nga giingon ni Jesus nga Siya lamang ang agianan?","Nagsimba mi sa “Langit.” Parehas ba kini sa “Dios” sa Bibliya?","Gihisgotan sa Yiguandao ang pagpalambo sa Dalan aron mahimong santos. Ang “kaluwasan” ba maoy bunga sa paningkamot o sa grasya?","Gitudlo sa among templo ang tulo ka yugto sa katalagman. Unsay giingon sa Bibliya bahin sa katapusan ug paghukom?","Nagkinahanglan ba og mga ritwal ang pag-ampo kang Jesus? Unsa ang kalahian niini sa among pagtahod sa Langit?","Si Jesus ba sa Bibliya parehas sa Jesus sa among templo (usa sa lima ka santos)?","Lawom ang akong pagkalambigit sa among templo. Kung makaila ko kang Jesus, namakak ba ko sa akong mga magtutudlo ug mga kauban sa pagtuo?","Maayo ang akong mga kauban sa pagtuo. Ngano nga giingon sa Bibliya nga ang tanan adunay sala ug nagkinahanglan og Manluluwas?","Naghisgot mi sa “Ginoo sa Kahitas-an” ug “pagbalik sa Langit.” Unsa ang langit ug kinabuhing dayon sa Bibliya?","Nangita mi sa Dalan ug nagsunog og insenso. Unsa ang hitsura sa pagsimba sa Bibliya?","Ngano nga giingon sa Bibliya nga si Jesus ang Anak sa Dios? Unsa ang kalahian niini sa tawo nga nagpalambo ug nahimong dios?","Ang tanan sa akong pamilya naa sa templo. Giunsa nako pagsulti kanila nga gusto kong masabtan si Jesus?","Gihatagan og bili sa Yiguandao ang pagtahod sa ginikanan ug pamatasan. Unsay gitudlo sa Bibliya bahin sa pamilya?","Sa among templo adunay “pagpangita sa Dalan” ug “magtutudlo nga nagpasa.” Ang pagsunod kang Jesus naglakip sa bawtismo. Unsa ang kalahian?","Nakabati kog kalinaw kaniadto sa templo. Unsa ang kalahian sa kalinaw nga gihatag ni Jesus?","Unsa ang bili sa akong nangaging praktis ug maayong mga buhat atubangan sa Dios?","Naa koy mga pagduha-duha apan nahadlok kong giingnan nga huyang ang akong pagtuo. Mahimo ba kong mangutana nga tinuoray?","Gusto kong makaila kang Jesus. Hain nga bahin sa Bibliya ang labing maayo nga sugdan?","Kung mag-ampo ko kang Jesus, kinahanglan ba nga mobiya ko una sa templo? Unsa ang akong masulti isip unang sentensya?"],"muslim":["Nagtuo ko nga usa ra ang Dios. Dili ba ang pagtuo sa “Trinidad” sa mga Kristiyano maoy tulo ka dios?","Gitahod namo si Isa (Jesus). Ngano nga giingon sa Bibliya nga Siya ang Anak sa Dios?","Gihisgotan sa Quran ug Bibliya si Abraham (Ibrahim) ug si Moises (Musa). Unsa ang kalahian nila?","Naglaum ang mga Muslim sa paraiso pinaagi sa lima ka haligi ug maayong buhat. Ngano nga giingon sa Bibliya nga ang kaluwasan maoy pinaagi sa grasya?","Gilansang ba gyud ug gipatay si Jesus? Ngano nga kinahanglan ang Iyang kamatayon?","Giingon sa uban nga giusab ang Bibliya. Kasaligan ba kini? Unsa ang ebidensya?","Unsang makasaysayanon nga ebidensya ang anaa alang sa pagkabanhaw ni Jesus?","Nag-ampo ko lima ka higayon matag adlaw. Giunsa sa mga Kristiyano pag-ampo? Kinahanglan ba kini nga adunay piho nga porma?","Nakasala ko. Giunsa sa Dios pagpasaylo sumala sa akong tradisyon, ug unsa ang kapasayloan sa Bibliya?","Kung interesado ko kang Jesus, giunsa kini pagtan-aw sa akong pamilya ug komunidad? Giunsa nako pagpanalipod sa akong kaugalingon ug sa mga higot sa pamilya?","Mahimo ba kong mobasa lang sa Bibliya aron makaila kang Jesus nga dili makiglalis sa akong pamilya?","Unsay giingon sa Bibliya bahin sa pagkatawo ni Jesus? Propeta ra ba, o labaw pa?","Giingon sa Bibliya nga ang Dios gugma. Nahibalo ko sa kaluoy sa Dios. Unsa ang pagkaparehas ug kalahian?","Nag-inom ba og alak o mokaon og baboy ang mga Kristiyano? Unsay gitudlo sa Bibliya bahin sa pagkaon?","Sa Adlaw sa Paghukom, unsaon nako pagkasiguro nga maluwas ko?","Unsa ang buot ipasabot sa “ang Pulong nahimong unod”? Unsaon sa Dios pagkahimong tawo?","Giunsa sa mga Kristiyano pagtan-aw ang balaang gubat ug kapintasan? Giunsa ni Jesus pagtudlo ang pagtagad sa mga kaaway?","Nahimong Muslim ko sukad pagkabata. Kung mosunod ko kang Jesus, pagluib ba kana?","Giunsa nako pagbasa nga hilom ang Maayong Balita sumala ni Juan aron makaila kang Jesus?","Kung gusto kong mag-ampo kang Jesus, mahimo ba kong mogamit sa akong kaugalingong pulong? Unsa ang unang sentensya?"],"atheist":["Mahimo ipasabot sa siyensya ang gigikanan sa uniberso. Ngano nga kinahanglan pa nato ang Dios?","Nagsumpaki ba ang ebolusyon sa paglalang sa Bibliya?","Wala pa nako makita ang Dios. Unsang ebidensya ang anaa nga Siya naglungtad?","Kung ang Dios gamhanan ug mahigugmaon, ngano nga adunay mga gubat, sakit ug katalagman?","Dili kinahanglan ang relihiyon sa pamatasan. Ngano nga kinahanglan pa nato ang pagtuo?","Sa kasaysayan adunay Krusada ug mga gubat sa relihiyon. Dili ba kini ang problema sa pagtuo?","Ang pipila ka istorya sa Bibliya (sama sa mga milagro) murag dili makatarunganon. Giunsa nako pagbasa niini?","Nabuhi ba gyud si Jesus sa kasaysayan? Unsang mga rekord sa kasaysayan ang anaa?","Unsang makasaysayanon nga basihan ang anaa alang sa pagkabanhaw? Dili ba gimugna kini sa mga tinun-an?","Dili ba ang pagtuo usa lang ka sikolohikal nga kahupayan ug pag-ikyas gikan sa reyalidad?","Dili ba mas sayon nga ang kamatayon mao ang katapusan? Ngano nga hisgotan pa ang kinabuhing dayon?","Kung walay Dios, asa gikan ang kahulogan sa kinabuhi?","Giunsa sa mga Kristiyano pagsagubang ang ilang kaugalingong pagduha-duha ug mga pangutana? Mahimo ba kong mohatag niini?","Nakakita kog mga Kristiyano nga ang ilang pulong ug lihok dili magkasumpay. Dili ba kini nagpamatuod nga bakak ang pagtuo?","Dili ba ang “pagtuo” nagpasabot sa pagtugyan sa paghunahuna?","Kung gusto kong tan-awon og seryoso si Jesus, unsang tinamdan ang angay nakong gamiton ug unsa ang unang basahon?","Molihok ba gyud ang pag-ampo? Aduna bay paagi nga masulayan nako kini sa akong kaugalingon?","Ngano nga giingon sa Bibliya nga ang mga tawo adunay “sala”? Sa akong hunahuna wala koy nahimo nga makalilisang.","Unsa ang talagsaon sa tudlo ni Jesus nga angay sa seryosong pagtagad?","Nagduhaduha pa ko, apan andam akong mosulay sa pag-ampo kausa. Unsa ang akong masulti?"]};
P.rules = [
 [/^(Sun|Mon|Tue|Wed|Thu|Fri|Sat)$/, function(m){ return WD[m[1]]; }],
 [/^in (\d+) min$/, function(m){ return 'human sa ' + m[1] + ' ka minuto'; }],
 [/^in (\d+) hr(?: (\d+) min)?$/, function(m){ return 'human sa ' + m[1] + ' ka oras' + (m[2] ? ' ug ' + m[2] + ' ka minuto' : ''); }],
 [/^in (\d+) days?(?: (\d+) hr)?$/, function(m){ return 'human sa ' + m[1] + ' ka adlaw' + (m[2] ? ' ug ' + m[2] + ' ka oras' : ''); }],
 [/^You finished the whole book of (.+)!$/, function(m){ return 'Nahuman na ninyo ang tibuok libro sa ' + m[1] + '!'; }],
 [/^(.+) — cleared!$/, function(m){ return m[1] + ' — nahuman na!'; }],
 [/^Wow! You finished (.+)! 🎉$/, function(m){ return 'Wow! Nahuman na ninyo ang ' + m[1] + '! 🎉'; }],
 [/^Medal (\d+) · (\d+) chapters$/, function(m){ return 'Medalya ' + m[1] + ' · ' + m[2] + ' ka kapitulo'; }],
 [/^(\d+) days ago$/, function(m){ return m[1] + ' ka adlaw ang milabay'; }],
 [/^Reading “(.+)”; has not started this plan$/, function(m){ return 'Nagabasa sa “' + m[1] + '”; wala pa niya masugdi kini nga plano'; }],
 [/^They are (\d+) day\(s\) ahead; catch up together$/, function(m){ return 'Nag-una siya og ' + m[1] + ' ka adlaw; atong sundan siya nga magkauban'; }],
 [/^You are (\d+) day\(s\) ahead; encourage them$/, function(m){ return 'Nag-una kamo og ' + m[1] + ' ka adlaw; dasiga siya'; }],
 [/^Volume (\d+)$/, function(m){ return 'Tomo ' + m[1]; }],
 [/^✗ Font failed to load \((.*)\)\. Check the network and tap the font button again\.$/, function(m){ return '✗ Wala ma-load ang font (' + m[1] + '). Susiha ang network ug i-tap pag-usab ang buton sa font.'; }],
 [/^Could not open the camera \((.*)\)\.$/, function(m){ return 'Wala maabli ang kamera (' + (m[1] === 'unknown' ? 'wala mahibaloi ang hinungdan' : m[1]) + ').'; }],
 [/^Congratulations — you finished the whole book of (.+)!$/, function(m){ return 'Maayo kaayo — nahuman na ninyo ang tibuok libro sa ' + m[1] + '!'; }],
 [/^  Points (\d+) \/ (\d+)$/, function(m){ return '  Puntos ' + m[1] + ' / ' + m[2]; }],
 [/^Review missed \((\d+)\)$/, function(m){ return 'Susiha ang mga nasaypan (' + m[1] + ')'; }],
 [/^The answer is a (.+)$/, function(m){ var T = {person:'tawo', place:'dapit', object:'butang', event:'panghitabo'}; var k = m[1].toLowerCase(); return 'Ang tubag niini usa ka ' + (T[k] || m[1]); }],
 [/^Worth (\d+) points? now — fewer hints, more points$/, function(m){ return 'Kantidad karon: ' + m[1] + ' ka puntos — mas gamay nga pahiwatig, mas daghang puntos'; }],
 [/^Yes \(\+(\d+)\)$/, function(m){ return 'Oo (+' + m[1] + ')'; }],
 [/^I got (\d+) \/ (\d+) on the (quiz|riddles) for (.+)!$/, function(m){ return 'Nakakuha ko og ' + m[1] + ' / ' + m[2] + ' sa ' + (m[3] === 'quiz' ? 'kuiz' : 'mga tigmo') + ' alang sa “' + m[4] + '” sa 321 Interaktibong Bibliya!'; }],
 [/^(\d+) riddles — hints appear one by one; guess early for more points$/, function(m){ return m[1] + ' ka tigmo — isa-isang makita ang mga pahiwatig; mas sayo mopanag-an, mas daghang puntos'; }],
 [/^(\d+) multiple-choice questions with instant explanations; misses go to your notebook$/, function(m){ return m[1] + ' ka pangutana nga adunay mga pilianan ug dayong esplikasyon; ang mga sayop moadto sa inyong notebook'; }],
 [/^(\d+) missed questions to review$/, function(m){ return m[1] + ' ka nasaypan nga pangutana nga susihon'; }]
];

